#ifndef CPPBPF_USER_OBJECT_HPP
#define CPPBPF_USER_OBJECT_HPP

#include <bpf/libbpf.h>
#include <cerrno>
#include <utility>

namespace cppbpf::user {

/*
 * Owns a skeleton generated by "bpftool gen skeleton" and destroys it when
 * it goes out of scope:
 *
 *   auto obj = cppbpf::user::object<basic>::open();
 *   if (!obj)
 *           return -errno;
 *   obj->rodata->target = 1;
 *   int err = obj.load();
 *
 * Errors are returned as negative errno values, as in libbpf.
 */
template <class Skel>
class object {
public:
	object() = default;

	object(object &&other) noexcept :
		skel_(std::exchange(other.skel_, nullptr))
	{
	}

	object &operator=(object &&other) noexcept
	{
		if (this != &other) {
			reset();
			skel_ = std::exchange(other.skel_, nullptr);
		}
		return *this;
	}

	object(const object &) = delete;
	object &operator=(const object &) = delete;

	~object()
	{
		reset();
	}

	/* Open the object; on failure the result is empty and errno is set. */
	static object open(const struct bpf_object_open_opts *opts = nullptr)
	{
		return object(Skel::open(opts));
	}

	/* Open and load the object; on failure the result is empty. */
	static object open_and_load()
	{
		return object(Skel::open_and_load());
	}

	int load()
	{
		return skel_ ? Skel::load(skel_) : -EINVAL;
	}

	int attach()
	{
		return skel_ ? Skel::attach(skel_) : -EINVAL;
	}

	void detach()
	{
		if (skel_)
			Skel::detach(skel_);
	}

	explicit operator bool() const
	{
		return skel_;
	}

	Skel *get() const
	{
		return skel_;
	}

	Skel *operator->() const
	{
		return skel_;
	}

private:
	explicit object(Skel *skel) : skel_(skel)
	{
	}

	/* Keeps errno, which may hold the error of a failed open. */
	void reset()
	{
		if (skel_) {
			int saved = errno;
			Skel::destroy(skel_);
			errno = saved;
		}
		skel_ = nullptr;
	}

	Skel *skel_ = nullptr;
};

} /* namespace cppbpf::user */

#endif /* CPPBPF_USER_OBJECT_HPP */
